def Encode(Text):
    if Text == "":
        return ""
    Result = ""
    Count = 1
    for Index in range(1, len(Text)):
        if Text[Index] == Text[Index - 1]:
            Count = Count + 1
        else:
            Result = Result + str(Count) + Text[Index - 1]
            Count = 1
    Result = Result + str(Count) + Text[-1]
    return Result

def Decode(Code):
    Result = ""
    Digits = ""
    for Ch in Code:
        if Ch.isdigit():
            Digits = Digits + Ch
        else:
            Result = Result + Ch * int(Digits)
            Digits = ""
    return Result

