Calls = 0

def BinarySearch(Data, Target, Low, High):
    global Calls
    Calls = Calls + 1
    if Low > High:
        return -1
    Mid = (Low + High) // 2
    if Data[Mid] == Target:
        return Mid
    elif Data[Mid] < Target:
        return BinarySearch(Data, Target, Mid + 1, High)
    else:
        return BinarySearch(Data, Target, Low, Mid - 1)

