def title_case(name):
    result = ""
    start_of_word = True
    for ch in name:
        if ch == " ":
            result = result + ch
            start_of_word = True
        elif start_of_word:
            result = result + ch.upper()
            start_of_word = False
        else:
            result = result + ch.lower()
    return result

