class Ride:
    def __init__(self, rider, km):
        self.__rider = rider
        self.__km = km

    def get_rider(self):
        return self.__rider

    def get_km(self):
        return self.__km

    def fare(self):
        return 100 + 40 * self.__km


class RickshawRide(Ride):
    def __init__(self, rider, km):
        super().__init__(rider, km)

    def fare(self):                       # overrides Ride.fare
        return 70 + 25 * self.get_km()


class CarRide(Ride):
    def __init__(self, rider, km, air_con):
        super().__init__(rider, km)
        self.__air_con = air_con

    def fare(self):                       # overrides Ride.fare
        cost = 150 + 55 * self.get_km()
        if self.__air_con:
            cost = cost * 1.1
        return round(cost, 2)

