def process_readings(filename):
    totals = {}
    counts = {}
    valid = 0
    invalid = 0
    try:
        file = open(filename, "r")
    except FileNotFoundError:
        print("Cannot open", filename)
        return
    for line in file:
        try:
            station, value = line.strip().split(",")
