        print(station, round(totals[station] / counts[station], 2))

class Stack:
    def __init__(self, size):
        self.__items = [""] * size
        self.__top = -1                  # -1 means empty
        self.__size = size

    def push(self, item):
        if self.__top == self.__size - 1:
            return False                 # stack full
        self.__top = self.__top + 1
        self.__items[self.__top] = item
        return True

    def pop(self):
        if self.__top == -1:
            return None                  # stack empty
        item = self.__items[self.__top]
        self.__top = self.__top - 1
        return item

    def is_empty(self):
        return self.__top == -1


def balanced(expression):
    pairs = {")": "(", "]": "[", "}": "{"}
    s = Stack(len(expression))
    for ch in expression:
        if ch in "([{":
            s.push(ch)
        elif ch in ")]}":
            if s.pop() != pairs[ch]:     # empty stack or wrong type of bracket
                return False
    return s.is_empty()

NULL = -1
SIZE = 10
data = [0] * SIZE
left = [NULL] * SIZE
right = [NULL] * SIZE
root = NULL
next_free = 0

def add_node(value):
    global root, next_free
    if next_free == SIZE:
        print("Tree full")
        return
    new = next_free
    data[new] = value
    next_free = next_free + 1
    if root == NULL:
        root = new
        return
    current = root
    while True:
        if value < data[current]:
            if left[current] == NULL:
                left[current] = new
                return
            current = left[current]
        else:
            if right[current] == NULL:
                right[current] = new
                return
            current = right[current]

def in_order(node):
    if node != NULL:
        in_order(left[node])
        print(data[node], end=" ")
        in_order(right[node])

def find(value):
    current = root
    comparisons = 0
    while current != NULL:
        comparisons = comparisons + 1
        if data[current] == value:
            return comparisons
        if value < data[current]:
            current = left[current]
        else:
            current = right[current]
    return -comparisons            # negative: not found after this many comparisons

def insertion_sort(items):
    comparisons = 0
    for i in range(1, len(items)):
        key = items[i]
        j = i - 1
        while j >= 0:
            comparisons = comparisons + 1
            if items[j] > key:
                items[j + 1] = items[j]      # shift larger item right
                j = j - 1
            else:
                break
        items[j + 1] = key
    return comparisons

def binary_search(items, target):
    low = 0
    high = len(items) - 1
    while low <= high:
        mid = (low + high) // 2
        if items[mid] == target:
            return mid
        elif items[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return -1

def ways(n):
    if n == 1:
        return 1                 # base case: one step left
    if n == 2:
        return 2                 # base case: 1+1 or 2
    return ways(n - 1) + ways(n - 2)   # general case

def ways_iterative(n):
    if n <= 2:
        return n
    a, b = 1, 2
    for _ in range(n - 2):
        a, b = b, a + b
    return b
